76	/// Which text-like pair is currently open.
77	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
78	enum OpenText {
79	    /// No text or thinking block is open.
80	    None,
81	    /// A `TEXT_MESSAGE_START` … `TEXT_MESSAGE_END` pair is open.
82	    Message,
83	    /// A `THINKING_TEXT_MESSAGE_START` … `THINKING_TEXT_MESSAGE_END` pair is open.
84	    Thinking,
85	}
86	
87	/// Which text-like pair [`EventMapper::open_text`] should open. Two variants, not
88	/// [`OpenText`]'s three — opening "no block" is not a request this method can be asked
89	/// to satisfy, so the type itself rules that call out rather than the body handling it.
90	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
91	enum TextKind {
92	    /// Open a `TEXT_MESSAGE_START` … `TEXT_MESSAGE_END` pair.
93	    Message,
94	    /// Open a `THINKING_TEXT_MESSAGE_START` … `THINKING_TEXT_MESSAGE_END` pair.
95	    Thinking,
96	}
