98	/// One occurrence of a provider call id: one tool call of the run.
99	#[derive(Debug, Clone)]
100	struct Occurrence {
101	    /// The AG-UI `toolCallId` of this occurrence: the provider id, or `{id}~{n}`.
102	    agui_id: String,
103	    /// Whether a `ToolCallDelta` with `name: Some(..)` was seen for this occurrence.
104	    named: bool,
105	    /// Whether the `ToolCallItem` of this occurrence was seen.
106	    item_seen: bool,
107	}
