109	/// Stateful `AgentEvent` → AG-UI frame mapper for exactly one run.
110	pub(crate) struct EventMapper {
111	    /// Client-supplied (or generated) thread id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
112	    thread_id: String,
113	    /// Client-supplied (or generated) run id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
114	    run_id: String,
115	    /// Which text-like pair (message or thinking) is currently open, if any.
116	    open_text: OpenText,
117	    /// Id of the currently-open text or thinking message.
118	    current_message: String,
119	    /// Monotonic counter behind `msg-N` ids. Stream-local uniqueness is all AG-UI
120	    /// requires, and deterministic ids let tests assert exact frame sequences.
121	    next_message: u32,
122	    /// Whether the current turn's assistant text has already been streamed via
123	    /// `TokenDelta`. Distinct from `open_text == OpenText::Message`: a `ToolCallDelta`
124	    /// closes the text block (via `close_text`) well before the matching
125	    /// `MessageOutput` arrives, so checking "is a message open right now" would miss
126	    /// that this text was already streamed and re-emit it.
127	    streamed_text: bool,
128	    /// Provider call id → its latest occurrence. A provider id can repeat in one run
129	    /// (see the module doc), so every other per-call field is keyed on the
130	    /// occurrence's AG-UI id instead.
131	    current: HashMap<String, Occurrence>,
132	    /// Every AG-UI id that this run already gave to an occurrence. An alias is never
133	    /// one of these, so it never equals a provider id that the run emitted.
134	    used_ids: HashSet<String>,
135	    /// AG-UI id of the call currently being streamed — has an open `TOOL_CALL_START`
136	    /// and no `TOOL_CALL_END` yet. `None` if no call is currently open.
137	    open_call: Option<String>,
138	    /// Tool name per AG-UI call id, recorded from whichever `ToolCallDelta` first
139	    /// carries one. Only one delta of a call carries `name`, but the delta that finally
140	    /// opens that call's span may be a continuation (its buffer resuming, or a
141	    /// revisit), so the name has to be remembered rather than read off the delta at
142	    /// hand — otherwise those spans render as `"unknown"`.
143	    call_names: HashMap<String, String>,
144	    /// Calls whose deltas arrived while a *different* call was open, or while the
145	    /// call waits for its name (see `awaiting_name`): `(AG-UI id, accumulated args)`.
146	    /// AG-UI permits only one active tool-call span at a time, while core's `ToolCallDelta`s for different ids may interleave freely
147	    /// (`paigasus-helikon-core/src/model.rs:56`) — buffering instead of closing and
148	    /// resuming preserves every args chunk exactly once and never emits an unmatched
149	    /// `TOOL_CALL_END`. A `Vec`, not a map, so flush order is deterministic.
150	    buffered_calls: Vec<(String, String)>,
151	    /// AG-UI call ids whose span has been emitted *and* closed. A `ToolCallItem`
152	    /// arrives long after the deltas it describes, by which time the call's span may already
153	    /// be closed — by its own delta path or by a foreign event that interrupted it.
154	    /// Without this record the item's arm cannot tell "already rendered" from "never
155	    /// streamed, synthesize it", and emits a second complete span for one call.
156	    completed_calls: HashSet<String>,
157	    /// AG-UI ids of the occurrences of a reused provider id that an unnamed delta
158	    /// started, and that no delta has named yet. Their deltas are buffered, so that
159	    /// `TOOL_CALL_START` carries the name that arrives on a later delta.
160	    awaiting_name: HashSet<String>,
161	    /// Whether a `STEP_STARTED` is currently unmatched.
162	    step_open: bool,
163	}
164	
165	impl EventMapper {
166	    /// Create a mapper for one run.
167	    // Constructed by the AG-UI SSE endpoint (SMA-461 Task 6, src/agui/sse.rs) and the
168	    // AG-UI WebSocket endpoint (SMA-461 Task 7, src/agui/ws.rs), one per run in both.
169	    pub(crate) fn new(thread_id: String, run_id: String) -> Self {
170	        Self {
171	            thread_id,
172	            run_id,
173	            open_text: OpenText::None,
174	            current_message: String::new(),
175	            next_message: 0,
176	            streamed_text: false,
177	            current: HashMap::new(),
178	            used_ids: HashSet::new(),
179	            open_call: None,
180	            call_names: HashMap::new(),
181	            buffered_calls: Vec::new(),
182	            completed_calls: HashSet::new(),
183	            awaiting_name: HashSet::new(),
184	            step_open: false,
185	        }
186	    }
187	
188	    /// Map one event, emitting any bracketing frames it implies.
189	    // Called per event by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI
190	    // WebSocket endpoint (SMA-461 Task 7) as each drains an `Agent` run.
191	    pub(crate) fn push(&mut self, ev: &AgentEvent) -> Vec<Value> {
192	        let mut out = Vec::new();
193	        match ev {
194	            AgentEvent::RunStarted { .. } => {
195	                out.push(event::run_started(&self.thread_id, &self.run_id));
196	            }
197	            AgentEvent::TurnStarted { .. } => {
198	                self.close_text(&mut out);
199	                // A tool-call span must not cross the `STEP_FINISHED`/`STEP_STARTED`
200	                // boundary below — it would close inside the *next* step.
201	                self.close_call(&mut out);
202	                self.close_step(&mut out);
203	                self.streamed_text = false;
204	                self.step_open = true;
205	                out.push(event::step_started("turn"));
206	            }
207	            AgentEvent::TokenDelta { text } => {
208	                self.close_call(&mut out);
209	                self.open_text(TextKind::Message, &mut out);
210	                if !text.is_empty() {
211	                    self.streamed_text = true;
212	                    out.push(event::text_message_content(&self.current_message, text));
213	                }
214	            }
215	            AgentEvent::ReasoningDelta { text } => {
216	                self.close_call(&mut out);
217	                self.open_text(TextKind::Thinking, &mut out);
218	                if !text.is_empty() {
219	                    out.push(event::thinking_content(&self.current_message, text));
220	                }
221	            }
222	            AgentEvent::ToolCallDelta {
223	                call_id,
224	                name,
225	                args_delta,
226	            } => {
227	                self.close_text(&mut out);
228	                let call_id = &self.occurrence_for_delta(call_id, name.is_some());
229	                if let Some(name) = name {
230	                    self.awaiting_name.remove(call_id);
231	                    self.call_names
232	                        .entry(call_id.clone())
233	                        .or_insert_with(|| name.clone());
234	                }
235	                if self.open_call.as_deref() == Some(call_id.as_str()) {
236	                    // A continuation of the currently-open call.
237	                    out.push(event::tool_call_args(call_id, args_delta));
238	                } else if self.open_call.is_none() && !self.awaiting_name.contains(call_id) {
239	                    // Nothing else is streaming and the call does not wait for its
240	                    // name: open this call now. If chunks for it were buffered while
241	                    // another call held the single active span, or while it waited
242	                    // for its name, replay them first — they were received before this one, and a
243	                    // client concatenating `TOOL_CALL_ARGS` deltas would otherwise
244	                    // rebuild the call's arguments out of order.
245	                    let buffered = self.take_buffered(call_id);
246	                    out.push(event::tool_call_start(
247	                        call_id,
248	                        self.name_of(call_id),
249	                        &self.current_message,
250	                    ));
251	                    if let Some(buffered) = buffered {
252	                        out.push(event::tool_call_args(call_id, &buffered));
253	                    }
254	                    out.push(event::tool_call_args(call_id, args_delta));
255	                    self.open_call = Some(call_id.clone());
256	                } else {
257	                    // A different call is streaming (AG-UI permits only one active
258	                    // span), or this new occurrence of a reused id waits for its
259	                    // name (`TOOL_CALL_START` carries it): buffer this id's content
260	                    // rather than emitting a START now — it is flushed as a complete span once
261	                    // its own `ToolCallItem` arrives, when a later delta resumes it
262	                    // above, or at the latest when the run ends.
263	                    match self.buffered_calls.iter_mut().find(|(id, _)| id == call_id) {
264	                        Some(entry) => entry.1.push_str(args_delta),
265	                        None => self
266	                            .buffered_calls
267	                            .push((call_id.clone(), args_delta.clone())),
268	                    }
269	                }
270	            }
271	            AgentEvent::ToolCallItem { item } => {
272	                self.close_text(&mut out);
273	                if let Item::ToolCall {
274	                    call_id,
275	                    name,
276	                    args,
277	                } = item
278	                {
279	                    let call_id = &self.occurrence_for_item(call_id);
280	                    if self.open_call.as_deref() == Some(call_id.as_str()) {
281	                        // The call this item describes is the one currently open.
282	                        self.close_call(&mut out);
283	                    } else if let Some(buffered) = self.take_buffered(call_id) {
284	                        // Deltas for this call were buffered while another call was
285	                        // open: flush the whole thing now as one complete,
286	                        // self-contained span. Nothing guarantees `ToolCallItem`s
287	                        // arrive in the order their calls opened, so close whatever
288	                        // is still open first — a complete span emitted inside
289	                        // another one would overlap.
290	                        self.close_call(&mut out);
291	                        self.emit_span(call_id, name, &buffered, &mut out);
292	                    } else if self.completed_calls.contains(call_id) {
293	                        // This call's span is already emitted and closed — by its own
294	                        // deltas above, or by a foreign event (a `TokenDelta`, another
295	                        // call's item) that had to close it to take the single active
296	                        // span. Synthesizing here would emit a second complete span
297	                        // for one call id.
298	                    } else {
299	                        // No deltas were streamed for this call (non-streaming
300	                        // provider): synthesize the whole triple from the item's own
301	                        // args so the client still sees a complete call — again, not
302	                        // nested inside whatever call is currently open.
303	                        self.close_call(&mut out);
304	                        self.emit_span(call_id, name, &args.to_string(), &mut out);
305	                    }
306	                } else {
307	                    out.push(self.custom("helikon.unknown", ev));
308	                }
309	            }
310	            AgentEvent::ToolOutputItem { item } => {
311	                self.close_call(&mut out);
312	                self.close_text(&mut out);
313	                if let Item::ToolResult { call_id, content } = item {
314	                    // The result belongs to the current occurrence of its provider id:
315	                    // in a sequential flow a result comes before the next call that
316	                    // could reuse the id. With no occurrence, the result uses the
317	                    // provider id, or the next free `{id}~{n}` when the run already
318	                    // emitted that id (for example as the alias of another call). The
319	                    // run counts the id as used, so a later call with that provider
320	                    // id gets an alias.
321	                    let call_id = match self.current.get(call_id) {
322	                        Some(occ) => occ.agui_id.clone(),
323	                        None => {
324	                            let id = self.unused_id(call_id);
325	                            self.used_ids.insert(id.clone());
326	                            id
327	                        }
328	                    };
329	                    if let Some(buffered) = self.take_buffered(&call_id) {
330	                        // Only possible under `ParallelAgent`: the call is still
331	                        // buffered. Flush it first, with its name, so its result never
332	                        // precedes its own span.
333	                        let name = self.name_of(&call_id).to_owned();
334	                        self.emit_span(&call_id, &name, &buffered, &mut out);
335	                    }
336	                    out.push(event::tool_call_result(&call_id, &text_of(content)));
337	                } else {
338	                    out.push(self.custom("helikon.unknown", ev));
339	                }
340	            }
341	            AgentEvent::MessageOutput { item } => {
342	                // Take the single active span before emitting anything: a synthesized
343	                // text triple nested inside an open `TOOL_CALL_START` would break
344	                // AG-UI's one-active-span rule.
345	                self.close_call(&mut out);
346	                if self.streamed_text {
347	                    // Deltas already streamed this text; only close it.
348	                    self.close_text(&mut out);
349	                } else {
350	                    // No deltas were emitted (non-streaming provider, workflow agent):
351	                    // synthesize the full triple, or the client renders nothing at all.
352	                    // Also closes any dangling thinking block if only `ReasoningDelta`s
353	                    // preceded this `MessageOutput` with no `TokenDelta` at all.
354	                    self.close_text(&mut out);
355	                    let content = match item {
356	                        Item::AssistantMessage { content, .. } => text_of(content),
357	                        _ => String::new(),
358	                    };
359	                    if !content.is_empty() {
360	                        let id = self.new_message_id();
361	                        out.push(event::text_message_start(&id));
362	                        out.push(event::text_message_content(&id, &content));
363	                        out.push(event::text_message_end(&id));
364	                    }
365	                }
366	                self.streamed_text = false;
367	            }
368	            AgentEvent::HandoffItem { .. } => {
369	                self.retire_unfinished_calls(&mut out);
370	                out.push(self.custom("helikon.handoff", ev));
371	            }
372	            AgentEvent::AgentUpdated { .. } => out.push(self.custom("helikon.agent_updated", ev)),
373	            AgentEvent::GuardrailTriggered { .. } => out.push(self.custom("helikon.guardrail", ev)),
374	            AgentEvent::ApprovalRequested { call_id, .. } => {
375	                // Keep `call_id` as the provider id (it matches
376	                // `RunDeferred.calls[].call_id`). Add `tool_call_id`, the AG-UI id
377	                // of the current occurrence, so a client can connect the approval
378	                // to the call's span.
379	                let mut frame = self.custom("helikon.approval", ev);
380	                if let Some(value) = frame["value"].as_object_mut() {
381	                    value.insert(
382	                        "tool_call_id".to_owned(),
383	                        Value::String(self.agui_id_of(call_id)),
384	                    );
385	                }
386	                out.push(frame);
387	            }
388	            AgentEvent::PermissionDenied { .. } => {
389	                out.push(self.custom("helikon.permission_denied", ev));
390	            }
391	            AgentEvent::RepairStarted { .. } => out.push(self.custom("helikon.repair", ev)),
392	            AgentEvent::StructuredOutputFailed { .. } => {
393	                out.push(self.custom("helikon.structured_output_failed", ev));
394	            }
395	            AgentEvent::RunCompleted { .. } => {
396	                self.close_all(&mut out);
397	                self.streamed_text = false;
398	                out.push(event::run_finished(&self.thread_id, &self.run_id));
399	            }
400	            AgentEvent::UserMessageInjected { .. } => {
401	                out.push(self.custom("helikon.user_message_injected", ev));
402	            }
403	            // AG-UI has no "stopped" run event. A stop is a controlled end, not a
404	            // failure, so the stream ends with `RUN_FINISHED`; the CUSTOM frame before
405	            // it carries the reason and usage.
406	            AgentEvent::RunStopped { .. } => {
407	                self.close_all(&mut out);
408	                self.streamed_text = false;
409	                out.push(self.custom("helikon.run_stopped", ev));
410	                out.push(event::run_finished(&self.thread_id, &self.run_id));
411	            }
412	            AgentEvent::RunFailed { error } => {
413	                self.close_all(&mut out);
414	                self.streamed_text = false;
415	                out.push(event::run_error("AGENT_ERROR", error));
416	            }
417	            // `AgentEvent` is `#[non_exhaustive]`: a variant added to core later must
418	            // degrade to a lossless CUSTOM event rather than vanish.
419	            other => out.push(self.custom("helikon.unknown", other)),
420	        }
421	        out
422	    }
423	
424	    /// Close any pairs still open. Only needed when a stream ends without a terminal
425	    /// event; the terminal arms already close every open pair themselves.
426	    // Called by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI WebSocket
427	    // endpoint (SMA-461 Task 7) once their channel from the underlying `Agent` stream
428	    // closes, in case that stream ended without a terminal event (e.g. a misbehaving
429	    // agent, or a connection dropped mid-run).
430	    pub(crate) fn finish(&mut self) -> Vec<Value> {
431	        let mut out = Vec::new();
432	        self.close_all(&mut out);
433	        out
434	    }
435	
436	    /// Build a `CUSTOM` frame carrying the full serialized event as its `value`.
437	    fn custom(&self, name: &str, ev: &AgentEvent) -> Value {
438	        event::custom(name, to_value(ev))
439	    }
440	
441	    /// Allocate the next deterministic `msg-N` id.
442	    fn new_message_id(&mut self) -> String {
443	        let id = format!("msg-{}", self.next_message);
444	        self.next_message += 1;
445	        id
446	    }
447	
448	    /// Ensure a text-like pair of kind `kind` is open, closing any different kind
449	    /// that is currently open first. A no-op if `kind` is already open.
450	    fn open_text(&mut self, kind: TextKind, out: &mut Vec<Value>) {
451	        let target = match kind {
452	            TextKind::Message => OpenText::Message,
453	            TextKind::Thinking => OpenText::Thinking,
454	        };
455	        if self.open_text == target {
456	            return;
457	        }
458	        self.close_text(out);
459	        let id = self.new_message_id();
460	        self.current_message = id.clone();
461	        match kind {
462	            TextKind::Message => out.push(event::text_message_start(&id)),
463	            TextKind::Thinking => out.push(event::thinking_start(&id)),
464	        }
465	        self.open_text = target;
466	    }
467	
468	    /// Close whichever text-like pair is currently open, if any.
469	    fn close_text(&mut self, out: &mut Vec<Value>) {
470	        match self.open_text {
471	            OpenText::Message => out.push(event::text_message_end(&self.current_message)),
472	            OpenText::Thinking => out.push(event::thinking_end(&self.current_message)),
473	            OpenText::None => {}
474	        }
475	        self.open_text = OpenText::None;
476	    }
477	
478	    /// Close whichever tool call is currently open, if any, and record it as done so
479	    /// its `ToolCallItem` — which always arrives later — does not render it twice.
480	    fn close_call(&mut self, out: &mut Vec<Value>) {
481	        if let Some(id) = self.open_call.take() {
482	            out.push(event::tool_call_end(&id));
483	            self.completed_calls.insert(id);
484	        }
485	    }
486	
487	    /// The AG-UI id for a `ToolCallDelta` of provider id `call_id`. Any delta, named
488	    /// or not, starts a new occurrence when the current one already had its
489	    /// `ToolCallItem` (the item comes after all deltas of a call), or when `call_id`
490	    /// has no occurrence yet. A name-carrying delta (`has_name`) also starts one when
491	    /// the current occurrence already had a name. An unnamed delta before the item
492	    /// stays on the current occurrence, and a name that arrives on a later delta
493	    /// attaches to the occurrence that the first delta started. When an unnamed
494	    /// delta starts a new occurrence that gets an alias (a reused id: the current
495	    /// occurrence already had its item, or the run used the id before, for example
496	    /// for an occurrence that a handoff retired), the new occurrence waits for its
497	    /// name (`awaiting_name`).
498	    fn occurrence_for_delta(&mut self, call_id: &str, has_name: bool) -> String {
499	        if let Some(occ) = self.current.get_mut(call_id) {
500	            if !(occ.item_seen || (has_name && occ.named)) {
501	                occ.named |= has_name;
502	                return occ.agui_id.clone();
503	            }
504	        }
505	        let agui_id = self.new_occurrence(call_id);
506	        if let Some(occ) = self.current.get_mut(call_id) {
507	            occ.named = has_name;
508	        }
509	        if agui_id != call_id && !has_name {
510	            self.awaiting_name.insert(agui_id.clone());
511	        }
512	        agui_id
513	    }
514	
515	    /// The AG-UI id for a `ToolCallItem` of provider id `call_id`. The item starts a
516	    /// new occurrence when the current one already had its item (a non-streamed call
517	    /// that reuses the id), or when `call_id` has no occurrence yet.
518	    fn occurrence_for_item(&mut self, call_id: &str) -> String {
519	        if let Some(occ) = self.current.get_mut(call_id) {
520	            if !occ.item_seen {
521	                occ.item_seen = true;
522	                return occ.agui_id.clone();
523	            }
524	        }
525	        let agui_id = self.new_occurrence(call_id);
526	        if let Some(occ) = self.current.get_mut(call_id) {
527	            occ.item_seen = true;
528	        }
529	        agui_id
530	    }
531	
532	    /// Start a new occurrence of provider id `call_id` and return its AG-UI id:
533	    /// `call_id` itself when the run has not used it, else `{call_id}~{n}` with the
534	    /// smallest `n` ≥ 2 that the run has not used.
535	    fn new_occurrence(&mut self, call_id: &str) -> String {
536	        let agui_id = self.unused_id(call_id);
537	        self.used_ids.insert(agui_id.clone());
538	        self.current.insert(
539	            call_id.to_owned(),
540	            Occurrence {
541	                agui_id: agui_id.clone(),
542	                named: false,
543	                item_seen: false,
544	            },
545	        );
546	        agui_id
547	    }
548	
549	    /// The first AG-UI id for provider id `call_id` that the run has not used:
550	    /// `call_id` itself, else `{call_id}~{n}` with the smallest `n` ≥ 2 that is not
551	    /// used. It does not mark the id as used.
552	    fn unused_id(&self, call_id: &str) -> String {
553	        if self.used_ids.contains(call_id) {
554	            (2u64..)
555	                .map(|n| format!("{call_id}~{n}"))
556	                .find(|alias| !self.used_ids.contains(alias))
557	                .expect("an unbounded range always yields an unused alias")
558	        } else {
559	            call_id.to_owned()
560	        }
561	    }
562	
563	    /// Retire every occurrence that did not have its `ToolCallItem` when a
564	    /// `HandoffItem` arrives. Core drops the non-transfer calls of a handoff
565	    /// response, so no item comes for them. Each one that is still open or buffered
566	    /// is closed or flushed as a complete span, and its provider id loses its
567	    /// occurrence, so the child's next call with that id starts a new occurrence.
568	    /// The ids stay in `used_ids`. Occurrences that had their item (the transfer
569	    /// call) stay, so the transfer result still finds its AG-UI id.
570	    fn retire_unfinished_calls(&mut self, out: &mut Vec<Value>) {
571	        let mut retired: HashSet<String> = HashSet::new();
572	        self.current.retain(|_, occ| {
573	            if occ.item_seen {
574	                true
575	            } else {
576	                retired.insert(occ.agui_id.clone());
577	                false
578	            }
579	        });
580	        if retired.is_empty() {
581	            return;
582	        }
583	        for id in &retired {
584	            self.awaiting_name.remove(id);
585	        }
586	        let open_retired = self
587	            .open_call
588	            .as_ref()
589	            .is_some_and(|id| retired.contains(id));
590	        let buffered_retired = self
591	            .buffered_calls
592	            .iter()
593	            .any(|(id, _)| retired.contains(id));
594	        if !(open_retired || buffered_retired) {
595	            return;
596	        }
597	        self.close_text(out);
598	        self.close_call(out);
599	        let (flush, keep): (Vec<_>, Vec<_>) = std::mem::take(&mut self.buffered_calls)
600	            .into_iter()
601	            .partition(|(id, _)| retired.contains(id));
602	        self.buffered_calls = keep;
603	        for (id, args) in flush {
604	            let name = self.name_of(&id).to_owned();
605	            self.emit_span(&id, &name, &args, out);
606	        }
607	    }
608	
609	    /// The AG-UI id of the current occurrence of provider id `call_id`, or `call_id`
610	    /// itself when it has none (a result for a call this mapper never saw).
611	    fn agui_id_of(&self, call_id: &str) -> String {
612	        self.current
613	            .get(call_id)
614	            .map_or_else(|| call_id.to_owned(), |occ| occ.agui_id.clone())
615	    }
616	
617	    /// Emit one complete, self-contained span for AG-UI id `call_id` and record it
618	    /// as closed.
619	    fn emit_span(&mut self, call_id: &str, name: &str, args: &str, out: &mut Vec<Value>) {
620	        out.push(event::tool_call_start(call_id, name, &self.current_message));
621	        out.push(event::tool_call_args(call_id, args));
622	        out.push(event::tool_call_end(call_id));
623	        self.completed_calls.insert(call_id.to_owned());
624	    }
625	
626	    /// The tool name recorded for AG-UI id `call_id`, falling back to `"unknown"` only
627	    /// when no delta for it ever carried one.
628	    fn name_of(&self, call_id: &str) -> &str {
629	        self.call_names
630	            .get(call_id)
631	            .map_or("unknown", String::as_str)
632	    }
633	
634	    /// Remove and return the args buffered for AG-UI id `call_id` while a different call
635	    /// held the active span, if any.
636	    fn take_buffered(&mut self, call_id: &str) -> Option<String> {
637	        let pos = self
638	            .buffered_calls
639	            .iter()
640	            .position(|(id, _)| id == call_id)?;
641	        Some(self.buffered_calls.remove(pos).1)
642	    }
643	
644	    /// Close a still-open `STEP_STARTED`, if any.
645	    fn close_step(&mut self, out: &mut Vec<Value>) {
646	        if self.step_open {
647	            out.push(event::step_finished("turn"));
648	            self.step_open = false;
649	        }
650	    }
651	
652	    /// Close every still-open pair: text/thinking, the open tool call, every
653	    /// still-buffered tool call (each as a complete span), then the step. Nothing
654	    /// may be left buffered once a run terminates.
655	    fn close_all(&mut self, out: &mut Vec<Value>) {
656	        self.close_text(out);
657	        self.close_call(out);
658	        for (id, args) in std::mem::take(&mut self.buffered_calls) {
659	            let name = self.name_of(&id).to_owned();
660	            self.emit_span(&id, &name, &args, out);
661	        }
662	        self.close_step(out);
663	    }
664	}
665	
666	/// Serialize an event for a `CUSTOM` frame's `value`, degrading to `null` rather than
667	/// failing — a frame with a null value still tells the client the event happened.
668	fn to_value(ev: &AgentEvent) -> Value {
669	    serde_json::to_value(ev).unwrap_or(Value::Null)
670	}
671	
672	/// Concatenate the text blocks of a content list, ignoring non-text parts.
673	fn text_of(content: &[ContentPart]) -> String {
674	    content
675	        .iter()
676	        .filter_map(|c| match c {
677	            ContentPart::Text { text } => Some(text.as_str()),
678	            _ => None,
679	        })
680	        .collect()
681	}
