    /// them. They go to the current occurrence, so no args chunk is lost.
    #[test]
    fn held_chunks_go_to_the_current_occurrence_at_the_run_end() {
        let events = vec![
            turn(1),
            tc_delta("a", Some("lookup"), "{\\"q\\":"),
            AgentEvent::HandoffItem {
                from: "triage".to_owned(),
                to: "billing".to_owned(),
